-- XP/candy/shiny multipliers become columns like type_boost (display labels
-- are now generated by the UI). community_progress is dropped: it always
-- equalled the event's summed progress. Unique-species events store one row
-- per species instead of an array plus a count.

alter table public.events
  add column xp_multiplier numeric not null default 1
    check (xp_multiplier > 0 and xp_multiplier <= 100),
  add column candy_multiplier numeric not null default 1
    check (candy_multiplier > 0 and candy_multiplier <= 100),
  add column shiny_multiplier numeric not null default 1
    check (shiny_multiplier > 0 and shiny_multiplier <= 100);

update public.events e
set xp_multiplier    = coalesce(m.xp, 1),
    candy_multiplier = coalesce(m.candy, 1),
    shiny_multiplier = coalesce(m.shiny, 1)
from (
  select e.id,
    max((b->>'value')::numeric) filter (where b->>'type' = 'xp_multiplier') as xp,
    max((b->>'value')::numeric) filter (where b->>'type' = 'candy_multiplier') as candy,
    max((b->>'value')::numeric) filter (where b->>'type' = 'shiny_rate_multiplier') as shiny
  from public.events e
  cross join lateral jsonb_array_elements(e.bonuses) b
  group by e.id
) m
where m.id = e.id;

alter table public.events
  drop constraint events_bonuses_check,
  drop column bonuses,
  drop constraint events_community_progress_nonneg,
  drop column community_progress;

create table public.event_species (
  event_id uuid not null references public.events (id) on delete cascade,
  user_id uuid not null references public.users (id) on delete cascade,
  pokedex_number integer not null references public.pokemon_species (id),
  caught_at timestamptz not null default now(),
  primary key (event_id, user_id, pokedex_number)
);

insert into public.event_species (event_id, user_id, pokedex_number, caught_at)
select p.event_id, p.user_id, s.pokedex_number, p.updated_at
from public.event_progress p
join public.events e on e.id = p.event_id and e.tracked_stat = 'unique_species'
cross join lateral (select distinct unnest(p.species) as pokedex_number) s;

delete from public.event_progress p
using public.events e
where e.id = p.event_id and e.tracked_stat = 'unique_species';

alter table public.event_progress drop column species;

alter table public.event_species enable row level security;
